346		value, err := expectBool(right)
347		if err != nil {
348			return renderResult{}, err
349		}
350		placeholder := r.addBoolArg(value)
351		column := qualifyColumn(r.dialect, field.Column)
352		return renderResult{
353			sql: fmt.Sprintf("%s %s %s", column, sqlOperator(op), placeholder),
354		}, nil
