483	func (r *renderer) renderElementInCondition(cond *ElementInCondition) (renderResult, error) {
484		field, ok := r.schema.Field(cond.Field)
485		if !ok {
486			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
487		}
488		if field.Kind != FieldKindJSONList {
489			return renderResult{}, errors.Errorf("field %q is not a tag list", cond.Field)
490		}
491	
492		lit, err := expectLiteral(cond.Element)
493		if err != nil {
494			return renderResult{}, err
495		}
496		str, ok := lit.(string)
497		if !ok {
498			return renderResult{}, errors.New("tags membership requires string literal")
499		}
500	
501		switch r.dialect {
502		case DialectSQLite:
503			sql := fmt.Sprintf("%s LIKE %s", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`%%"%s"%%`, str)))
504			return renderResult{sql: sql}, nil
505		case DialectMySQL:
506			sql := fmt.Sprintf("JSON_CONTAINS(%s, %s)", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`"%s"`, str)))
507			return renderResult{sql: sql}, nil
508		case DialectPostgres:
509			sql := fmt.Sprintf("%s @> jsonb_build_array(%s::json)", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`"%s"`, str)))
510			return renderResult{sql: sql}, nil
511		default:
512			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
513		}
514	}
